    for cat, cname, cform, cdesc in canonical_math_facts:
        if cname not in seen_terms:
            seen_terms.add(cname)
            parsed.append((cat, cname, cform, cdesc))

    for line in EXTRA_MATH_COMPACT.strip().splitlines():
        for tok in line.split("||"):
            tok = tok.strip()
            if not tok or tok.count(":") < 2:
                continue
            left, cform, cdesc = tok.split(":", 2)
            cat, cname = (left.split("]", 1)[0].replace("[", "").strip(), left.split("]", 1)[1].strip()) if "]" in left else ("수학", left.strip())
            if cname and cname not in seen_terms:
                seen_terms.add(cname)
                parsed.append((cat, cname, cform.strip(), cdesc.strip()))

    split_idx = max(0, len(parsed) - 100)
    head_concepts = parsed[:split_idx]
    tail_concepts = parsed[split_idx:]

    items: List[Tuple[str, str, str, str]] = []
    used_terms = set()
    used_ctxs = set()

    def _add_math_item(t: str, a: str, c: str, tp: str) -> None:
        if t in used_terms:
            t = f"{t} [정리]"
        if c in used_ctxs:
            c = f"{c} ({t})"
        used_terms.add(t)
        used_ctxs.add(c)
        items.append((t, a, c, tp))

    # 1. Head Math Concepts (Principle/Definition -> Theorem/Identity Name)
    for cat, cname, cform, cdesc in head_concepts:
        safe_desc = cdesc.replace(cname, "이 수학 정리·공식")
        term = cname
        ans = f"{cname} ({cform})" if cform != cname and len(cform) <= 48 else cname
        ctx = f"[{cat}] {safe_desc} — 위 수학적 성질과 원리에 해당하는 정리·공식은?"
        tip = f"[{cat}] {cname} | 공식: {cform} | 해설: {cdesc}"
        _add_math_item(term, ans, ctx, tip)

    # 2. Math Symbolic Formulas & Identities (Formula -> Theorem/Concept)
    for cat, cname, cform, cdesc in parsed:
        term_b = f"{cform} ({cat})" if cform != cname and f"{cform} ({cat})" not in used_terms else f"[{cat} 공식] {cname}"
        ans_b = cform
        ctx_b = f"[{cat}] '{cname}'의 정확한 수식(항등식·공식·성립 조건)을 제시하시오."
        tip_b = f"{cname}: {cform} ({cdesc})"
        _add_math_item(term_b, ans_b, ctx_b, tip_b)

    # 3. Math Necessary Conditions & Geometric Proofs
    for cat, cname, cform, cdesc in parsed:
        if len(items) + len(tail_concepts) >= 1090:
            break
        term_c = f"[{cat} 증명·성질] {cform[:36]}" if cform != cname else f"[{cat} 성질] {cname}"
        if term_c in used_terms:
            term_c = f"[{cat} 정리] {cname}"
        ans_c = cdesc
        ctx_c = f"[{cat}] 수식 '{cform}' ({cname})이 성립하기 위한 전제 조건과 수학적 활용 원리는?"
        tip_c = f"[{cat}] {cname}: {cform} — {cdesc}"
        _add_math_item(term_c, ans_c, ctx_c, tip_c)

    # 4. Tail Primary Standalone Math Concepts (100 brand-new primary concepts at the tail, covering cards[-50:]!)
    for cat, cname, cform, cdesc in tail_concepts:
        safe_desc = cdesc.replace(cname, "이 수학 정리·공식")
        term = cname
        ans = f"{cname} ({cform})" if cform != cname and len(cform) <= 48 else cname
        ctx = f"[{cat}] {safe_desc} — 위 수학적 성질과 원리에 해당하는 정리·공식은?"
        tip = f"[{cat}] {cname} | 공식: {cform} | 해설: {cdesc}"
        _add_math_item(term, ans, ctx, tip)

    return tuple(items)

