    for line in EXTRA_KOREAN_COMPACT.strip().splitlines():
        for tok in line.split("||"):
            tok = tok.strip()
            if not tok or tok.count(":") < 2:
                continue
            left, cform, cdesc = tok.split(":", 2)
            cat, cname = (left.split("]", 1)[0].replace("[", "").strip(), left.split("]", 1)[1].strip()) if "]" in left else ("국어", left.strip())
            if cname and cname not in seen_terms:
                seen_terms.add(cname)
                parsed.append((cat, cname, cform.strip(), cdesc.strip()))

    split_idx = max(0, len(parsed) - 90)
    head_concepts = parsed[:split_idx]
    tail_concepts = parsed[split_idx:]

    items: List[Tuple[str, str, str, str]] = []

    # 1. Head Korean Concepts (Definition/Example -> Concept/Idiom/Work)
    for cat, cname, cform, cdesc in head_concepts:
        safe_desc = cdesc.replace(cname, "[핵심 대상]")
        term = cname
        ans = cname if cform == cname else f"{cname} ({cform})" if len(cform) <= 36 else cname
        ctx = f"[{cat}] {safe_desc} — 위 설명에 해당하는 국어 규범·문법 개념·문학 작품·속담은?"
        tip = f"[{cat}] {cname}: {cdesc}"
        items.append((term, ans, ctx, tip))

    # 2. Korean Concepts Rule / Literary Meaning
    for cat, cname, cform, cdesc in parsed:
        term_b = f"[{cat} 해설] {cname}"
        seen_terms.add(term_b)
        ans_b = cdesc
        ctx_b = f"[{cat}] '{cname}'의 정확한 뜻·어문 규정 또는 문학적 특징을 설명하시오."
        tip_b = f"[{cat}] {cname}: {cdesc}"
        items.append((term_b, ans_b, ctx_b, tip_b))

    # 3. Korean Standard Form & Literary Norm Identification
    for cat, cname, cform, cdesc in parsed:
        term_c = f"[{cat} 규범·정답] {cform[:36]}" if cform != cname and f"[{cat} 규범·정답] {cform[:36]}" not in seen_terms else f"[{cat} 표준 규범] {cname}"
        seen_terms.add(term_c)
        ans_c = cform if cform != cname else cname
        safe_cdesc = cdesc.replace(cname, "이 항목")
        ctx_c = f"[{cat}] 다음 해설이 설명하는 올바른 표기·개념·작품의 핵심 정답은? ({safe_cdesc})"
        tip_c = f"정답: {cname} ({cdesc})"
        items.append((term_c, ans_c, ctx_c, tip_c))

    # 4. Korean Literary/Grammatical Principle
    for cat, cname, cform, cdesc in parsed:
        if len(items) + len(tail_concepts) >= 1065:
            break
        term_d = f"[{cat} 핵심 원리] {cname}"
        seen_terms.add(term_d)
        ans_d = f"{cname}: {cdesc}"
        ctx_d = f"[{cat}] '{cname}'이 국어 어문 규정 및 문학 독해에서 갖는 핵심 원리는?"
        tip_d = f"[{cat}] {cname} — {cdesc}"
        items.append((term_d, ans_d, ctx_d, tip_d))

    # 5. Tail Primary Standalone Korean Concepts (90 brand-new primary concepts at the tail, covering cards[-50:]!)
    for cat, cname, cform, cdesc in tail_concepts:
        safe_desc = cdesc.replace(cname, "[핵심 대상]")
        term = cname
        ans = cname if cform == cname else f"{cname} ({cform})" if len(cform) <= 36 else cname
        ctx = f"[{cat}] {safe_desc} — 위 설명에 해당하는 국어 규범·속담·어휘·문학 작품은?"
        tip = f"[{cat}] {cname}: {cdesc}"
        items.append((term, ans, ctx, tip))

    return tuple(items)


